import json
from pathlib import Path
import exchange_calendars as xc

cal = xc.get_calendar("XNYS", start="2020-01-01", end="2035-12-31")
sessions = {
    str(d.date()): {
        "open": "09:30",
        "close": row["close"].tz_convert("America/New_York").strftime("%H:%M"),
    }
    for d, row in cal.schedule.iterrows()
}
Path("lib/ct-calendar-data.ts").write_text(
    "// Generated by scripts/data/export-calendar.py using exchange-calendars 4.11.2 XNYS.\nexport const sessions: Record<string,{open:string;close:string}> = "
    + json.dumps(sessions, separators=(",", ":"))
    + ";\n"
)
